#!/usr/bin/python3
from pathlib import Path
import subprocess,hashlib,json,csv,io,re,argparse
parser=argparse.ArgumentParser(description='Read-only static field/cost audit; no compilation');parser.add_argument('--core-repo',required=True);parser.add_argument('--output-dir',type=Path,required=True);args=parser.parse_args();p=args.output_dir;assert not p.exists(),'New output revision required';p.mkdir(parents=True);core=args.core_repo;c='62dc1d179b5516e68b21b695c7a9c5d0667e9671'
def blob(path):return subprocess.check_output(['git','-C',core,'show',c+':'+path]).decode()
h=blob('src/gpgpu-sim/gpu-cache.h');inc=blob('src/gpgpu-sim/ep-l2-ft-cache.inc');abi=blob('src/gpgpu-sim/ep-l2-ft-interface.h')
assert re.search(r'enum role\s*\{\s*RESIDENT, BYPASS, WB\s*\}',h)
assert all(x in h for x in ['FREE,','RESIDENT_FILL_PENDING','RESIDENT_VALID','RESIDENT_DIRTY','BYPASS_FILL_PENDING','BYPASS_READY, WB_RESERVED, WB_STAGED'])
anchors=[('slot','gpu-cache.h','struct slot {','2+3+(A-7)+G+4+4+K','per physical slot; role/state independent-encoding scenario'),('PayloadHandle','ep-l2-ft-interface.h','struct PayloadHandle {','P+G','ID11; hardware G unspecified; software unsigned not hardware width'),('Tag_handle','gpu-cache.h','std::vector<ep_l2_payload_store::payload_handle> m_ep_l2_tag_payload;','1024(P+G)','common if B16 and U both pointerized; not entire incremental delta'),('WB_handle','gpu-cache.h','struct ft_wb_record {','128(P+G)','packet binding, valid/state separately required'),('front_reservation','gpu-cache.h','struct ft_replacement {','3(P+G)+P+10+2+4','exclude owner address, packet ID and saved rollback slot; copy latch counted separately'),('bank_arbiter','gpu-cache.h','request_result request(','4Q_b(P+G+op+E+valid)','bounded physical Q_b not established by software vector'),('physical_clock','ep-l2-ft-cache.inc','unsigned long long l2_cache::ft_physical_cycle() const','4 busy bits plus explicitly bounded arbitration state','m_cycle and monotonic assert are simulator bookkeeping, not a required 64-bit hardware clock register'),('warm_prefill','ep-l2-ft-cache.inc','bool l2_cache::ft_try_force_tag_access(','existing unique allocator owner and generation fields','source-only guard/binding; no additional free payload RAM'),('copy_reference_sidecar','gpu-cache.h','std::array<unsigned long long,4> copy_versions','software-only versions; separate mandated common latch=1024 data bits/slice','Do not synthesize reference versions as payload; physical copy latch comes from storage/port contract')]
rows=[]
for name,file,needle,formula,notes in anchors:
 text=abi if file=='ep-l2-ft-interface.h' else inc if file.endswith('.inc') else h
 assert needle in text,needle;line=text[:text.index(needle)].count('\n')+1
 rows.append({'component':name,'source_commit':c,'file':'src/gpgpu-sim/'+file,'anchor_line':line,'anchor':needle,'parameterized_bits':formula,'scope_or_exclusion':notes})
s=io.StringIO(newline='');w=csv.DictWriter(s,fieldnames=list(rows[0]),lineterminator='\n');w.writeheader();w.writerows(rows);(p/'FIELD_COST_LEDGER.csv').write_text(s.getvalue())
scenarios=[]
for N in [1168,1160]:
 for G in [8,16,32]:
  P=(N-1).bit_length();A=48;K=6;slot=2+3+(A-7)+G+4+4+K
  scenarios.append({'N':N,'A':A,'G_ILLUSTRATIVE_NOT_HARDWARE_MINIMUM':G,'K_ILLUSTRATIVE_NOT_PROVEN_BOUND':K,'P':P,'slot_bits_per_entry':slot,'gross_slot_metadata_bits':N*slot,'tag_handle_bits':1024*(P+G),'WB_handle_bits':128*(P+G),'reservation_known_fields_bits':3*(P+G)+P+10+2+4,'data_RAM_bits':N*128*8,'common_copy_latch_bits':1024,'RAM_plus_latch_KiB_per_slice':N/8+0.125,'RAM_plus_latch_MiB_chip':(N*128+128)*64/(1024**2),'not_total_area':True,'incremental_against_baseline':False})
# Independent reference point from explicit field list: 76 bits x1168.
assert next(r for r in scenarios if r['N']==1168 and r['G_ILLUSTRATIVE_NOT_HARDWARE_MINIMUM']==16)['gross_slot_metadata_bits']==88768
out={'source_commit':c,'source_status':'UNCOMPILED_CANDIDATE_STATIC_FIELD_AUDIT_ONLY','binary_sha256':None,'default_figures_are_cost_scenarios_not_measurements':True,'parameter_definitions':{'P':'ceil(log2 N)','A':'physical address width, assumed48 only for examples','G':'hardware generation width unknown; examples8/16/32','K':'pin counter width unknown; example6 requires independent maximum-ref proof','Q_b':'physical retry queue depth per bank unknown','E':'hardware arbitration age width unknown','J':'packet/control binding ID width unknown'},'scenarios':scenarios,'logic':{'handle_validation':'indexed lookup + occupied + G-bit equality; optional A-7 owner equality','free_slot_selection':'one eligible 292/290-slot bank class; bitmap+encoder OR free list as alternative implementations','oldest_tree':'per bank Q_b-1 E-bit compare nodes and ceil(log2 Q_b) ideal topology depth; excludes mux, wiring, wrap correctness','WAD_parallel_example':'128 equality units, each A-7 bit comparisons; not a gate count and not free CAM','paths':['Tag->handle validation->bank grant->RAM/read response','miss->WAD/landing/staging reservation->eligibility->free-slot select->commit/rollback','WB owner and ref check->bank send-read->actual lower acceptance->release','independent TVD lookup(+1 modeled cycle), RO generation/sector/backpressure extension']},'unknown_physical_outputs':{'area_mm2':None,'power_mW':None,'STA_frequency':None}}
(p/'COST_MODEL.json').write_text(json.dumps(out,ensure_ascii=False,sort_keys=True,indent=2)+'\n')
print(json.dumps({'source_field_anchors':len(rows),'scenarios':len(scenarios),'G16_N1168_slot_bits':88768,'RAM_plus_latch_KiB':146.125,'reservation_G16_known_bits':108}))

(p/'COST_SOURCE_AUDIT.json').write_text(json.dumps({'status':'PASS_STATIC_ONLY','source_commit':c,'anchors':rows,'runtime_qualification':False,'files':[{'path':f,'sha256':hashlib.sha256(blob(f).encode()).hexdigest()} for f in ['src/gpgpu-sim/gpu-cache.h','src/gpgpu-sim/ep-l2-ft-interface.h','src/gpgpu-sim/ep-l2-ft-cache.inc']]},indent=2,sort_keys=True)+'\n')
